INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('complaints','main','hero','{"lead": "How to make a complaint and what happens next.", "heading": "Complaints Policy", "intro": "<p>This policy has been reviewed and updated to ensure compliance with the <strong>Child, Youth and Family Services Act, 2017</strong> and <strong>Ontario Regulation 155/18</strong>. Updates include:</p><ul><li>Clarifying a child’s right to make a complaint verbally or in writing, privately, and to any person they trust</li><li>Establishing a clear requirement to acknowledge all complaints within 24 hours</li><li>Requiring an assessment of immediate action and supports needed to participate in the complaint review process</li><li>Ensuring complaints affecting a child are documented in the child’s file, with cross-referencing where applicable</li><li>Aligning timelines and documentation requirements into a single, comprehensive procedure</li></ul>", "bg": "", "variant": ""}',0,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('complaints','main','steps','{"heading": "", "steps": [{"reverse": false, "heading": "Policy Overview", "body": "<p>Complaints against the foster home and/or the Agency or Placing Agency must be reported and taken seriously by all parties. The nature and severity of complaints may vary greatly and can come from many sources. Specific procedures are given depending on the source and nature of the complaint. At all times, the safety and well-being of the child is paramount.</p><p>Verbal complaints must be documented and addressed in writing to the same criteria as written complaints. The complainant must at some point sign to verify a document outlining the complaint.</p><p>The person who is the subject of the complaint cannot be the one to respond to the complaint.</p><p>In all situations where there is a complaint against a foster home, it is the decision of the Agency alone to close the home. The Placing Agency may wish to remove its children from the home; however, they cannot determine how the Agency concludes the complaint process.</p><p>Where there is no protection concern and the complaint can be resolved without further involvement of protective services, all parties will seek to resolve the issue promptly and collaboratively.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.38.54-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.38.54-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.38.54-PM.png", "w": 891, "h": 499}}, {"reverse": false, "heading": "Records of complaints added to the foster home file will include:", "body": "<ul><li>The circumstances of the complaint and possible investigation</li><li>Who was involved</li><li>The way in which the investigation was conducted</li><li>The recommendation</li><li>The action taken</li></ul>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.16-PM-640.avif 640w, /assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.16-PM-1024.avif 1024w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.16-PM-640.webp 640w, /assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.16-PM-1024.webp 1024w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.16-PM.png", "w": 1056, "h": 593}}, {"reverse": false, "heading": "Right to Make a Complaint", "body": "<p>A child or young person in foster care has the right to make a complaint at any time regarding their care, treatment, or the actions or decisions of a foster parent, Agency staff, or the Agency itself.</p><p><strong>A complaint may be made:</strong></p><ul><li>Verbally or in writing</li><li>In private or in the presence of others</li><li>To any person the child feels comfortable with and trusts</li></ul><p><strong>This may include, but is not limited to:</strong></p><ul><li>A foster parent</li><li>An Agency staff member</li><li>A Resource Worker</li><li>The Program Supervisor</li><li>The Executive Director</li><li>A person designated by the Agency</li></ul><p>All individuals who receive a complaint are required to ensure the complaint is promptly communicated to the Agency for action.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.23-PM-640.avif 640w, /assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.23-PM-1024.avif 1024w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.23-PM-640.webp 640w, /assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.23-PM-1024.webp 1024w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.23-PM.png", "w": 1054, "h": 590}}, {"reverse": false, "heading": "General Requirements", "body": "<ul><li>Verbal complaints must be documented and addressed using the same criteria as written complaints.</li><li>The person who is the subject of the complaint shall not be responsible for responding to or reviewing the complaint.</li><li>The decision to close a foster home rests solely with the Agency.</li><li>Where no protection concern exists, complaints will be resolved collaboratively whenever possible.</li></ul>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.58-PM-640.avif 640w, /assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.58-PM-1024.avif 1024w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.58-PM-640.webp 640w, /assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.58-PM-1024.webp 1024w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.39.58-PM.png", "w": 1202, "h": 671}}, {"reverse": false, "heading": "Acknowledgement, Immediate Action, and Supports", "body": "<p>Upon receipt of a complaint, the Agency shall, within 24 hours:</p><ol><li>Acknowledge receipt of the complaint</li><li>Document the complaint</li><li>Assess whether immediate action is required to protect the child’s safety or well-being</li><li>Determine what supports the complainant may require</li></ol><p>Supports may include a trusted support person, advocacy assistance, or communication accommodations. The determination of supports shall be documented and reviewed as needed.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.12-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.12-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.12-PM.png", "w": 912, "h": 511}}, {"reverse": false, "heading": "Documentation Requirements", "body": "<p>Where a complaint relates to the care, treatment, or rights of a child:</p><ul><li>The nature of the complaint</li><li>Dates and timelines</li><li>Individuals involved</li><li>Actions taken and outcomes</li><li>Supports offered or provided</li></ul><p>A corresponding record may also be placed in the foster home file where applicable.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.19-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.19-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.19-PM.png", "w": 915, "h": 513}}, {"reverse": false, "heading": "Ombudsman", "body": "<p>A child in foster care has the right to speak privately with and have visits from the Ontario Ombudsman regarding a complaint. Children shall be informed of this right at placement, during each plan of care review, and as prescribed by legislation. Documentation of this review shall be signed and retained.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.34-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.34-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.34-PM.png", "w": 909, "h": 512}}, {"reverse": false, "heading": "Documentation Requirements", "body": "<p>Where a complaint relates to the care, treatment, or rights of a child:</p><ul><li>The nature of the complaint</li><li>Dates and timelines</li><li>Individuals involved</li><li>Actions taken and outcomes</li><li>Supports offered or provided</li></ul><p>A corresponding record may also be placed in the foster home file where applicable.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.44-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.44-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.44-PM.png", "w": 912, "h": 512}}], "sectionClass": "no-numbers with-decor program-section"}',1,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('complaints','main','richSection','{"sectionClass": "editor-content program-editor", "body": "<h2 style=\"text-align: center;\">Complaint Processes</h2><div class=\"grid-x grid-margin-x\"><div class=\"cell large-4 medium-4 small-12\"><strong>Community Complaint Regarding the Foster Home</strong><ul><li>Complaint assessed for severity</li><li>If investigation required, it commences within five working days</li><li>If no protection concern, Agency addresses complaint within 24 hours</li><li>Documentation completed in appropriate file(s)</li></ul></div><div class=\"cell large-4 medium-4 small-12\"><strong>Complaint from the Placing Agency</strong><ul><li>Agency discusses complaint with Placing Agency</li><li>Investigation follows if required</li><li>If no investigation required, addressed within 24 hours</li><li>Documentation completed</li></ul></div><div class=\"cell large-4 medium-4 small-12\"><strong>Complaint from a Foster Child</strong><ul><li>Child may bring complaint to any trusted person</li><li>Agency staff notified immediately</li><li>Placing Agency notified</li><li>CAS notified if protection concern identified</li><li>Immediate action and supports assessed</li><li>Complaint addressed within 24 hours</li><li>Documented in child’s file</li></ul></div></div>"}',2,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('complaints','main','steps','{"heading": "", "steps": [{"reverse": false, "heading": "Review of Complaint", "body": "<ul><li>Initial status update provided within 15 days</li><li>Further updates every 15 days until resolution<br>\nOutcome explained in language appropriate to the complainant</li><li>Where a child’s rights have been violated, procedures shall be reviewed and revised to prevent recurrence.</li></ul>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.53-PM-640.avif 640w, /assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.53-PM-1024.avif 1024w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.53-PM-640.webp 640w, /assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.53-PM-1024.webp 1024w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.40.53-PM.png", "w": 1050, "h": 594}}, {"reverse": false, "heading": "Review and Continual Development", "body": "<p>The Agency shall review the effectiveness of this policy within 12 months of the previous review.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.09-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.09-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.09-PM.png", "w": 918, "h": 512}}, {"reverse": false, "heading": "Submission to the Ministry", "body": "<p>Complaints shall be analyzed monthly and submitted no later than the 5th day of the following month using the SOR-RL website.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.15-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.15-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.15-PM.png", "w": 916, "h": 516}}, {"reverse": false, "heading": "Debriefing", "body": "<ul><li>Individuals related to the complaint shall be debriefed</li><li>The child shall have a support person present</li><li>Debriefing shall occur within seven days unless documented otherwise</li><li>Records of debriefings shall be maintained</li></ul>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.53-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.53-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.53-PM.png", "w": 923, "h": 517}}, {"reverse": false, "heading": "Required Notifications", "body": "<ul><li>Parent or legal guardian notified where applicable</li><li>Placing Agency notified in all cases</li><li>CAS notified if protection concerns arise</li><li>Serious Occurrence logged in SOR-RL where required</li><li>Complainant notified when review concludes</li></ul><p>Documentation confirming all required notifications shall be retained in the appropriate file.</p>", "img": {"avif": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.53-PM-640.avif 640w", "webp": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.53-PM-640.webp 640w", "jpg": "/assets/uploads/2026/03/Screenshot-2026-03-18-at-12.41.53-PM.png", "w": 923, "h": 517}}], "sectionClass": "no-numbers with-decor program-section"}',3,'published','');
